package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://app:app123@localhost:5432/inventory?sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category parameter required", http.StatusBadRequest)
		return
	}

	// Build query with parameterized category but dynamic sort
	baseQuery := "SELECT id, name, price, stock FROM products WHERE category = $1"

	if minPrice != "" {
		// Validate minPrice is numeric-ish
		if !isNumeric(minPrice) {
			http.Error(w, "invalid min_price", http.StatusBadRequest)
			return
		}
		baseQuery += " AND price >= " + minPrice
	}

	// Sort field - allow common columns
	if sortField != "" {
		// Developer attempted allowlist but made a mistake:
		// they check prefix instead of exact match
		allowed := []string{"name", "price", "stock", "id"}
		sortAllowed := false
		for _, a := range allowed {
			if strings.HasPrefix(strings.ToLower(sortField), a) {
				sortAllowed = true
				break
			}
		}
		if sortAllowed {
			baseQuery += " ORDER BY " + sortField
		}
	}

	rows, err := db.Query(baseQuery, category)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var name string
		var price float64
		var stock int
		rows.Scan(&id, &name, &price, &stock)
		if !first {
			w.Write([]byte(","))
		}
		fmt.Fprintf(w, `{"id":%d,"name":"%s","price":%.2f,"stock":%d}`, id, name, price, stock)
		first = false
	}
	w.Write([]byte("]"))
}

func isNumeric(s string) bool {
	for i, c := range s {
		if c == '.' && i > 0 {
			continue
		}
		if c < '0' || c > '9' {
			return false
		}
	}
	return len(s) > 0
}

// healthCheck for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
